const images = import.meta.glob(
  '/src/assets/**/*.{jpeg,jpg,png,gif,avif,webp}',
  {
    eager: true,
  },
)

/**
 * Imports an image from /src/assets and returns its metadata.
 * @param {string} src - Path to the image (e.g. '/src/assets/hero.jpg')
 * @returns {{ src: string, width: number, height: number, format: string }}
 */
export function importImage(src) {
  const keys = Object.keys(images)
  const key = keys.find(key => key.includes(src))
  if (!key) throw new Error(`Image ${src} not found`)
  return images[key].default
}

/**
 * Creates a media query string from min/max values or a custom query.
 * @param {Object} props
 * @param {number} [props.min]
 * @param {number} [props.max]
 * @param {string} [props.query]
 * @returns {string}
 */
export function getQuery(props) {
  const { min, max } = props
  let { query = '' } = props

  if (query) return query

  if (!min && !max)
    throw new Error('min or max must be declared in artDirection item')
  if (min) query += `(min-width: ${min}px)`
  if (max) query += `(max-width: ${max}px)`
  return query
}

/**
 * Normalizes any image input into a flat { src, width, height, srcset } for rendering.
 * Accepts a string path, a static import result, or an img()/getAstroImage result.
 * @param {string|Object} image
 * @returns {{ src: string, width: number, height: number, srcset?: string, format?: string }}
 */
export function resolveImage(image) {
  if (typeof image === 'string') image = importImage(image)

  if (image.attributes) {
    return {
      src: image.src,
      width: image.attributes.width,
      height: image.attributes.height,
      srcset: image.srcSet?.attribute,
      format: image.options?.format,
    }
  }

  return image
}
